function luhnClean(s){
  var t=String(s).replace(/[\s-]/g,'');
  if(!/^\d+$/.test(t)) throw new Error('仅允许数字、空格和短横线');
  return t;
}
function luhnChecksum(digits){
  var sum=0, alt=false;
  for(var i=digits.length-1;i>=0;i--){
    var d=digits.charCodeAt(i)-48;
    if(alt){ d*=2; if(d>9) d-=9; }
    sum+=d; alt=!alt;
  }
  return sum%10;
}
function luhnValidate(s){
  var t=luhnClean(s);
  if(t.length<2) throw new Error('号码至少 2 位');
  return luhnChecksum(t)===0;
}
function luhnCheckDigit(s){
  var t=luhnClean(s);
  return String((10-luhnChecksum(t+'0'))%10);
}
function cardBrand(s){
  var t=luhnClean(s);
  if(/^4\d{12}(\d{3})?(\d{3})?$/.test(t)) return 'Visa';
  if(/^(5[1-5]\d{14}|2(2[2-9]\d{12}|[3-6]\d{13}|7[01]\d{12}|720\d{12}))$/.test(t)) return 'Mastercard';
  if(/^3[47]\d{13}$/.test(t)) return 'American Express';
  if(/^62\d{14,17}$/.test(t)) return 'UnionPay 银联';
  if(/^(6011|65\d{2}|64[4-9]\d)\d{12,15}$/.test(t)) return 'Discover';
  if(/^35(2[89]|[3-8]\d)\d{12}$/.test(t)) return 'JCB';
  if(/^3(0[0-5]|[68]\d)\d{11}$/.test(t)) return 'Diners Club';
  return '未知卡组织';
}
function formatCard(s){
  var t=luhnClean(s), out=[];
  for(var i=0;i<t.length;i+=4) out.push(t.slice(i,i+4));
  return out.join(' ');
}
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { luhnValidate:luhnValidate, luhnCheckDigit:luhnCheckDigit, cardBrand:cardBrand, formatCard:formatCard, luhnClean:luhnClean };
}
if (typeof window !== 'undefined') {
  window.LuhnForgePure = { luhnValidate:luhnValidate, luhnCheckDigit:luhnCheckDigit, cardBrand:cardBrand, formatCard:formatCard, luhnClean:luhnClean };
}
